import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";

/* ============================================================
   DARA — KANBAN DE PRODUÇÃO AUDIOVISUAL
   Identidade visual extraída da proposta comercial (logo intacta,
   Montserrat + serif do wordmark, verde-grafite/dourado da marca).
   ============================================================ */

const LOGO_SRC =
  "data:image/png;base64,";

const STAGES = [
  { id: "GRAVADO", label: "Gravado", hint: "Recém-gravados" },
  { id: "DECUPAGEM", label: "Decupagem", hint: "Seleção de takes" },
  { id: "EDICAO", label: "Edição", hint: "Em edição" },
  { id: "FINALIZACAO", label: "Finalização", hint: "Processos técnicos" },
  { id: "REVISAO", label: "Revisão", hint: "Revisão interna" },
  { id: "ENVIADO", label: "Enviado", hint: "Aguardando cliente" },
  { id: "ALTERACAO", label: "Alteração", hint: "Cliente pediu ajuste" },
  { id: "CONCLUIDO", label: "Concluído", hint: "Entregue e aprovado" },
];

const CHECKLIST_DEFS = [
  ["colorGrading", "Color Grading"],
  ["audio", "Tratamento de áudio"],
  ["lettering", "Lettering / Motion"],
  ["legendas", "Legendas"],
  ["ortografia", "Revisão ortográfica"],
  ["exportacao", "Exportação"],
];

// PIN de acesso ao modo admin — troque este valor para o seu próprio PIN.
const ADMIN_PIN = "2026";

const PRIORITIES = ["Normal", "Alta", "Urgente"];
const FORMATS = ["Vertical 9:16", "Horizontal 16:9", "Quadrado 1:1", "Outro"];
const TYPES = [
  "Vídeo imobiliário",
  "Reels",
  "Institucional",
  "Depoimento",
  "Anúncio",
  "IA",
  "Outro",
];

function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}

function toISODate(d) {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x.toISOString().slice(0, 10);
}

function parseISODate(s) {
  const [y, m, d] = s.split("-").map(Number);
  return new Date(y, m - 1, d);
}

function addBusinessDays(date, days) {
  const d = new Date(date);
  let added = 0;
  while (added < days) {
    d.setDate(d.getDate() + 1);
    const day = d.getDay();
    if (day !== 0 && day !== 6) added++;
  }
  return d;
}

function businessDaysDiff(from, to) {
  const sign = to >= from ? 1 : -1;
  const start = sign === 1 ? from : to;
  const end = sign === 1 ? to : from;
  let count = 0;
  const cur = new Date(start);
  cur.setHours(0, 0, 0, 0);
  const endD = new Date(end);
  endD.setHours(0, 0, 0, 0);
  while (cur.getTime() < endD.getTime()) {
    cur.setDate(cur.getDate() + 1);
    const day = cur.getDay();
    if (day !== 0 && day !== 6) count++;
  }
  return sign * count;
}

function fmtDateBR(iso) {
  if (!iso) return "—";
  const d = parseISODate(iso);
  return d.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" });
}

function nowStamp() {
  return new Date().toLocaleString("pt-BR", {
    day: "2-digit",
    month: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function deadlineInfo(video) {
  if (video.stage === "CONCLUIDO") {
    return { level: "done", label: "Entregue", emoji: "✅", remaining: null };
  }
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const due = parseISODate(video.dueDate);
  const remaining = businessDaysDiff(today, due);
  if (remaining < 0)
    return {
      level: "late",
      label: `ATRASADO — ${Math.abs(remaining)} DIA${
        Math.abs(remaining) > 1 ? "S" : ""
      }`,
      emoji: "🔴",
      remaining,
    };
  if (remaining === 0)
    return { level: "today", label: "ENTREGA HOJE", emoji: "🔴", remaining };
  if (remaining === 1)
    return {
      level: "tomorrow",
      label: "Entrega amanhã",
      emoji: "🟠",
      remaining,
    };
  if (remaining === 2)
    return {
      level: "soon",
      label: `${remaining} dias úteis restantes`,
      emoji: "🟡",
      remaining,
    };
  return {
    level: "ok",
    label: `${remaining} dias úteis restantes`,
    emoji: "🟢",
    remaining,
  };
}

function sortScore(video) {
  const info = deadlineInfo(video);
  if (video.stage === "CONCLUIDO") return 999;
  const prio = video.priority === "Urgente" ? 0 : video.priority === "Alta" ? 1 : 2;
  let bucket;
  if (info.level === "late") bucket = 0;
  else if (info.level === "today") bucket = 1;
  else if (info.level === "tomorrow") bucket = 2;
  else bucket = 3 + prio;
  return bucket * 10000 + (info.remaining ?? 0) * 10 + prio;
}

function seedVideos() {
  const today = new Date();
  const iso = (offset) => toISODate(new Date(today.getFullYear(), today.getMonth(), today.getDate() + offset));
  const shoot1 = iso(-2);
  const due1 = toISODate(addBusinessDays(parseISODate(shoot1), 3));
  const shoot2 = iso(-1);
  const due2 = toISODate(addBusinessDays(parseISODate(shoot2), 3));
  const shoot3 = iso(-6);
  const due3 = toISODate(addBusinessDays(parseISODate(shoot3), 3));
  return [
    {
      id: uid(),
      client: "Mislene",
      title: "Gran Reserva — Pré-lançamento",
      shootDate: shoot1,
      dueDate: due1,
      editor: "Matheus",
      priority: "Alta",
      format: "Vertical 9:16",
      type: "Vídeo imobiliário",
      notes: "",
      filesLink: "",
      scriptLink: "",
      stage: "EDICAO",
      order: 0,
      checklist: Object.fromEntries(CHECKLIST_DEFS.map(([k]) => [k, false])),
      revisions: [],
      history: [
        { at: nowStamp(), text: "Vídeo cadastrado" },
        { at: nowStamp(), text: "Movido para EDIÇÃO" },
      ],
      createdAt: Date.now(),
    },
    {
      id: uid(),
      client: "Evelyn Britto",
      title: "Cobertura institucional — Verão",
      shootDate: shoot2,
      dueDate: due2,
      editor: "Matheus",
      priority: "Normal",
      format: "Horizontal 16:9",
      type: "Institucional",
      notes: "",
      filesLink: "",
      scriptLink: "",
      stage: "GRAVADO",
      order: 0,
      checklist: Object.fromEntries(CHECKLIST_DEFS.map(([k]) => [k, false])),
      revisions: [],
      history: [{ at: nowStamp(), text: "Vídeo cadastrado" }],
      createdAt: Date.now(),
    },
    {
      id: uid(),
      client: "Aline",
      title: "Apartamento alto padrão — Reels",
      shootDate: shoot3,
      dueDate: due3,
      editor: "Matheus",
      priority: "Urgente",
      format: "Vertical 9:16",
      type: "Reels",
      notes: "Cliente pediu troca de trilha.",
      filesLink: "",
      scriptLink: "",
      stage: "ALTERACAO",
      order: 0,
      checklist: Object.fromEntries(CHECKLIST_DEFS.map(([k]) => [k, false])),
      revisions: [
        {
          number: 1,
          requestedAt: nowStamp(),
          description: "Trocar música e corrigir lettering aos 00:32.",
          notes: "",
        },
      ],
      history: [
        { at: nowStamp(), text: "Vídeo cadastrado" },
        { at: nowStamp(), text: "Enviado ao cliente" },
        { at: nowStamp(), text: "Cliente solicitou alteração" },
      ],
      createdAt: Date.now(),
    },
  ];
}

const EMPTY_FORM = {
  client: "",
  title: "",
  shootDate: toISODate(new Date()),
  dueDate: "",
  dueDateEdited: false,
  editor: "",
  priority: "Normal",
  format: "Vertical 9:16",
  type: "Vídeo imobiliário",
  notes: "",
  filesLink: "",
  scriptLink: "",
};

export default function DaraKanban() {
  const [videos, setVideos] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [role, setRole] = useState("editor"); // editor | admin
  const [pinOpen, setPinOpen] = useState(false);
  const [pinValue, setPinValue] = useState("");
  const [pinError, setPinError] = useState(false);
  const [clientsInfo, setClientsInfo] = useState({});
  const [view, setView] = useState("kanban"); // kanban | hoje | clientes | financeiro
  const [search, setSearch] = useState("");
  const [quickFilter, setQuickFilter] = useState("todos");
  const [clientFilter, setClientFilter] = useState("");
  const [editorFilter, setEditorFilter] = useState("");
  const [priorityFilter, setPriorityFilter] = useState("");
  const [manualSort, setManualSort] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [form, setForm] = useState(EMPTY_FORM);
  const [lastShoot, setLastShoot] = useState(null);
  const [detailId, setDetailId] = useState(null);
  const [dragId, setDragId] = useState(null);
  const [saveState, setSaveState] = useState("idle");
  const saveTimer = useRef(null);

  // ---------- persistence ----------
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get("dara-videos", false);
        if (res && res.value) {
          setVideos(JSON.parse(res.value));
        } else {
          setVideos(seedVideos());
        }
      } catch (e) {
        setVideos(seedVideos());
      }
      try {
        const res2 = await window.storage.get("dara-clients-info", false);
        if (res2 && res2.value) setClientsInfo(JSON.parse(res2.value));
      } catch (e) {
        // sem dados salvos ainda, tudo bem
      } finally {
        setLoaded(true);
      }
    })();
  }, []);

  useEffect(() => {
    if (!loaded) return;
    (async () => {
      try {
        await window.storage.set("dara-clients-info", JSON.stringify(clientsInfo), false);
      } catch (e) {
        // ignora falha de rede pontual
      }
    })();
  }, [clientsInfo, loaded]);

  function updateClientInfo(name, patch) {
    setClientsInfo((prev) => ({
      ...prev,
      [name]: { ...(prev[name] || {}), ...patch },
    }));
  }

  function addExpense(desc, value) {
    setClientsInfo((prev) => ({
      ...prev,
      __expenses: [...(prev.__expenses || []), { id: uid(), desc, value: Number(value) || 0 }],
    }));
  }

  function removeExpense(id) {
    setClientsInfo((prev) => ({
      ...prev,
      __expenses: (prev.__expenses || []).filter((e) => e.id !== id),
    }));
  }

  useEffect(() => {
    if (!loaded) return;
    setSaveState("saving");
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      try {
        await window.storage.set("dara-videos", JSON.stringify(videos), false);
        setSaveState("saved");
      } catch (e) {
        setSaveState("error");
      }
    }, 350);
    return () => clearTimeout(saveTimer.current);
  }, [videos, loaded]);

  // ---------- derived ----------
  const clients = useMemo(
    () => Array.from(new Set(videos.map((v) => v.client))).sort(),
    [videos]
  );
  const editors = useMemo(
    () => Array.from(new Set(videos.map((v) => v.editor).filter(Boolean))).sort(),
    [videos]
  );

  const stats = useMemo(() => {
    const today = toISODate(new Date());
    const weekEnd = toISODate(addBusinessDays(new Date(), 5));
    const emProducao = videos.filter((v) => v.stage !== "CONCLUIDO").length;
    const estaSemana = videos.filter(
      (v) => v.stage !== "CONCLUIDO" && v.dueDate <= weekEnd
    ).length;
    const atrasados = videos.filter(
      (v) => v.stage !== "CONCLUIDO" && deadlineInfo(v).level === "late"
    ).length;
    const aguardando = videos.filter((v) => v.stage === "ENVIADO").length;
    const thisMonth = new Date().toISOString().slice(0, 7);
    const entreguesMes = videos.filter(
      (v) =>
        v.stage === "CONCLUIDO" &&
        v.history.some(
          (h) => h.text.includes("CONCLUÍDO") && h.at
        )
    ).length;
    return { emProducao, estaSemana, atrasados, aguardando, entreguesMes };
  }, [videos]);

  const filtered = useMemo(() => {
    const today = toISODate(new Date());
    const tomorrow = toISODate(addBusinessDays(new Date(), 1));
    const weekEnd = toISODate(addBusinessDays(new Date(), 5));
    return videos.filter((v) => {
      if (search) {
        const q = search.toLowerCase();
        if (
          !v.client.toLowerCase().includes(q) &&
          !v.title.toLowerCase().includes(q)
        )
          return false;
      }
      if (clientFilter && v.client !== clientFilter) return false;
      if (editorFilter && v.editor !== editorFilter) return false;
      if (priorityFilter && v.priority !== priorityFilter) return false;
      if (quickFilter === "atrasados") return deadlineInfo(v).level === "late";
      if (quickFilter === "hoje") return deadlineInfo(v).level === "today";
      if (quickFilter === "semana")
        return v.stage !== "CONCLUIDO" && v.dueDate <= weekEnd;
      return true;
    });
  }, [videos, search, clientFilter, editorFilter, priorityFilter, quickFilter]);

  function stageVideos(stageId) {
    const list = filtered.filter((v) => v.stage === stageId);
    if (manualSort) {
      return list.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
    }
    return list.sort((a, b) => sortScore(a) - sortScore(b));
  }

  // ---------- actions ----------
  function addHistory(video, text) {
    return { ...video, history: [...video.history, { at: nowStamp(), text }] };
  }

  function moveVideo(id, newStage) {
    setVideos((prev) =>
      prev.map((v) => {
        if (v.id !== id || v.stage === newStage) return v;
        const oldLabel = STAGES.find((s) => s.id === v.stage)?.label ?? v.stage;
        const newLabel = STAGES.find((s) => s.id === newStage)?.label ?? newStage;
        let nv = { ...v, stage: newStage };
        nv = addHistory(nv, `Movido de ${oldLabel} para ${newLabel.toUpperCase()}`);
        if (newStage === "ENVIADO") nv = addHistory(nv, "Enviado ao cliente");
        if (newStage === "CONCLUIDO") nv = addHistory(nv, "Movido para CONCLUÍDO");
        return nv;
      })
    );
  }

  function reorderWithinStage(id, targetId, stageId) {
    setVideos((prev) => {
      const stageList = prev
        .filter((v) => v.stage === stageId)
        .sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
      const rest = prev.filter((v) => v.stage !== stageId);
      const fromIdx = stageList.findIndex((v) => v.id === id);
      const toIdx = stageList.findIndex((v) => v.id === targetId);
      if (fromIdx === -1 || toIdx === -1) return prev;
      const [moved] = stageList.splice(fromIdx, 1);
      stageList.splice(toIdx, 0, moved);
      const reordered = stageList.map((v, i) => ({ ...v, order: i }));
      return [...rest, ...reordered];
    });
  }

  function updateVideo(id, patch) {
    setVideos((prev) => prev.map((v) => (v.id === id ? { ...v, ...patch } : v)));
  }

  function toggleChecklist(id, key) {
    setVideos((prev) =>
      prev.map((v) =>
        v.id === id
          ? { ...v, checklist: { ...v.checklist, [key]: !v.checklist[key] } }
          : v
      )
    );
  }

  function addRevision(id, description) {
    setVideos((prev) =>
      prev.map((v) => {
        if (v.id !== id) return v;
        const num = v.revisions.length + 1;
        let nv = {
          ...v,
          revisions: [
            ...v.revisions,
            { number: num, requestedAt: nowStamp(), description, notes: "" },
          ],
        };
        nv = addHistory(nv, `Alteração #${num} registrada`);
        return nv;
      })
    );
  }

  function deleteVideo(id) {
    setVideos((prev) => prev.filter((v) => v.id !== id));
    setDetailId(null);
  }

  function openNewModal(prefillFromShoot) {
    if (prefillFromShoot) {
      setForm({
        ...EMPTY_FORM,
        client: prefillFromShoot.client,
        shootDate: prefillFromShoot.shootDate,
        editor: prefillFromShoot.editor,
        filesLink: prefillFromShoot.filesLink,
        scriptLink: prefillFromShoot.scriptLink,
      });
    } else {
      setForm(EMPTY_FORM);
    }
    setModalOpen(true);
  }

  function submitForm(addAnother) {
    if (!form.client.trim() || !form.title.trim() || !form.shootDate) return;
    const shoot = parseISODate(form.shootDate);
    const due = form.dueDate
      ? form.dueDate
      : toISODate(addBusinessDays(shoot, 3));
    const newVideo = {
      id: uid(),
      client: form.client.trim(),
      title: form.title.trim(),
      shootDate: form.shootDate,
      dueDate: due,
      editor: form.editor.trim(),
      priority: form.priority,
      format: form.format,
      type: form.type,
      notes: form.notes,
      filesLink: form.filesLink,
      scriptLink: form.scriptLink,
      stage: "GRAVADO",
      order: 0,
      checklist: Object.fromEntries(CHECKLIST_DEFS.map(([k]) => [k, false])),
      revisions: [],
      history: [{ at: nowStamp(), text: "Vídeo cadastrado" }],
      createdAt: Date.now(),
    };
    setVideos((prev) => [...prev, newVideo]);
    setLastShoot({
      client: newVideo.client,
      shootDate: newVideo.shootDate,
      editor: newVideo.editor,
      filesLink: newVideo.filesLink,
      scriptLink: newVideo.scriptLink,
    });
    if (addAnother) {
      openNewModal({
        client: newVideo.client,
        shootDate: newVideo.shootDate,
        editor: newVideo.editor,
        filesLink: newVideo.filesLink,
        scriptLink: newVideo.scriptLink,
      });
    } else {
      setModalOpen(false);
    }
  }

  // due date auto-calc when shootDate changes (unless user edited manually)
  useEffect(() => {
    if (!modalOpen) return;
    if (form.dueDateEdited) return;
    if (!form.shootDate) return;
    const due = toISODate(addBusinessDays(parseISODate(form.shootDate), 3));
    setForm((f) => (f.dueDateEdited ? f : { ...f, dueDate: due }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [form.shootDate, modalOpen]);

  const detailVideo = videos.find((v) => v.id === detailId) || null;

  const todayList = useMemo(() => {
    const late = videos.filter((v) => v.stage !== "CONCLUIDO" && deadlineInfo(v).level === "late");
    const today = videos.filter((v) => deadlineInfo(v).level === "today");
    const tomorrow = videos.filter((v) => deadlineInfo(v).level === "tomorrow");
    const editing = videos.filter((v) => v.stage === "EDICAO");
    const changes = videos.filter((v) => v.stage === "ALTERACAO");
    return { late, today, tomorrow, editing, changes };
  }, [videos]);

  return (
    <div className="dk-root">
      <style>{CSS}</style>

      <header className="dk-header">
        <div className="dk-brand">
          <img src={LOGO_SRC} alt="Dara" className="dk-logo" />
          <div className="dk-brand-text">
            <span className="dk-brand-title">DARA</span>
            <span className="dk-brand-sub">PRODUÇÃO · FLUXO AUDIOVISUAL</span>
          </div>
        </div>
        <nav className="dk-nav">
          <button
            className={"dk-nav-btn" + (view === "kanban" ? " active" : "")}
            onClick={() => setView("kanban")}
          >
            Kanban
          </button>
          <button
            className={"dk-nav-btn" + (view === "hoje" ? " active" : "")}
            onClick={() => setView("hoje")}
          >
            Hoje
          </button>
          <button
            className={"dk-nav-btn" + (view === "clientes" ? " active" : "")}
            onClick={() => setView("clientes")}
          >
            Clientes
          </button>
          {role === "admin" && (
            <button
              className={"dk-nav-btn admin" + (view === "financeiro" ? " active" : "")}
              onClick={() => setView("financeiro")}
            >
              Financeiro
            </button>
          )}
        </nav>
        <button
          className="dk-admin-toggle"
          title={role === "admin" ? "Sair do modo admin" : "Entrar como admin"}
          onClick={() => {
            if (role === "admin") {
              setRole("editor");
              if (view === "financeiro") setView("kanban");
            } else {
              setPinValue("");
              setPinError(false);
              setPinOpen(true);
            }
          }}
        >
          {role === "admin" ? "🔓 Admin" : "🔒"}
        </button>
        <button className="dk-new-btn" onClick={() => openNewModal(null)}>
          + Novo vídeo
        </button>
      </header>

      <div className="dk-stats">
        <StatChip
          label="Em produção"
          value={stats.emProducao}
          active={quickFilter === "todos"}
          onClick={() => setQuickFilter("todos")}
        />
        <StatChip
          label="Entregas esta semana"
          value={stats.estaSemana}
          active={quickFilter === "semana"}
          onClick={() => setQuickFilter("semana")}
        />
        <StatChip
          label="Atrasados"
          value={stats.atrasados}
          tone="late"
          active={quickFilter === "atrasados"}
          onClick={() => setQuickFilter("atrasados")}
        />
        <StatChip
          label="Aguardando cliente"
          value={stats.aguardando}
          onClick={() => setView("kanban")}
        />
        <StatChip label="Entregues no mês" value={stats.entreguesMes} tone="done" />
        <span className={"dk-savebadge " + saveState}>
          {saveState === "saving" ? "salvando…" : saveState === "error" ? "erro ao salvar" : "salvo"}
        </span>
      </div>

      {view === "kanban" && (
        <>
          <div className="dk-filters">
            <div className="dk-quick">
              {[
                ["todos", "Todos"],
                ["atrasados", "Atrasados"],
                ["hoje", "Entrega hoje"],
                ["semana", "Esta semana"],
              ].map(([id, label]) => (
                <button
                  key={id}
                  className={"dk-chip" + (quickFilter === id ? " active" : "")}
                  onClick={() => setQuickFilter(id)}
                >
                  {label}
                </button>
              ))}
            </div>
            <select value={clientFilter} onChange={(e) => setClientFilter(e.target.value)}>
              <option value="">Por cliente</option>
              {clients.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
            <select value={editorFilter} onChange={(e) => setEditorFilter(e.target.value)}>
              <option value="">Por editor</option>
              {editors.map((e) => (
                <option key={e} value={e}>
                  {e}
                </option>
              ))}
            </select>
            <select value={priorityFilter} onChange={(e) => setPriorityFilter(e.target.value)}>
              <option value="">Por prioridade</option>
              {PRIORITIES.map((p) => (
                <option key={p} value={p}>
                  {p}
                </option>
              ))}
            </select>
            <input
              className="dk-search"
              placeholder="Buscar cliente ou vídeo…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            <button
              className={"dk-chip" + (manualSort ? " active" : "")}
              onClick={() => setManualSort((s) => !s)}
              title="Alternar ordenação"
            >
              {manualSort ? "Ordenação: manual" : "Ordenação: inteligente"}
            </button>
          </div>

          <div className="dk-board">
            {STAGES.map((stage) => {
              const list = stageVideos(stage.id);
              return (
                <div
                  key={stage.id}
                  className="dk-column"
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => {
                    e.preventDefault();
                    if (dragId) moveVideo(dragId, stage.id);
                    setDragId(null);
                  }}
                >
                  <div className="dk-col-head">
                    <span className="dk-col-title">{stage.label}</span>
                    <span className="dk-col-count">{list.length}</span>
                  </div>
                  <span className="dk-col-hint">{stage.hint}</span>
                  <div className="dk-col-body">
                    {list.map((v) => (
                      <VideoCard
                        key={v.id}
                        video={v}
                        onDragStart={() => setDragId(v.id)}
                        onDragOverCard={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                        onDropCard={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          if (dragId && dragId !== v.id) {
                            if (manualSort) reorderWithinStage(dragId, v.id, stage.id);
                            else moveVideo(dragId, stage.id);
                          }
                          setDragId(null);
                        }}
                        onOpen={() => setDetailId(v.id)}
                        onStageChange={(newStage) => moveVideo(v.id, newStage)}
                      />
                    ))}
                    {list.length === 0 && <div className="dk-empty">Nada por aqui</div>}
                  </div>
                </div>
              );
            })}
          </div>
        </>
      )}

      {view === "hoje" && (
        <div className="dk-today">
          <TodaySection title="🔴 Atrasados" items={todayList.late} onOpen={setDetailId} />
          <TodaySection title="🟠 Entregar hoje" items={todayList.today} onOpen={setDetailId} />
          <TodaySection title="🟡 Entregar amanhã" items={todayList.tomorrow} onOpen={setDetailId} />
          <TodaySection title="🎬 Em edição" items={todayList.editing} onOpen={setDetailId} />
          <TodaySection title="🔄 Alterações solicitadas" items={todayList.changes} onOpen={setDetailId} />
        </div>
      )}

      {view === "clientes" && (
        <div className="dk-clients">
          {clients.length === 0 && <div className="dk-empty">Nenhum cliente cadastrado ainda.</div>}
          {clients.map((c) => {
            const vids = videos.filter((v) => v.client === c);
            const done = vids.filter((v) => v.stage === "CONCLUIDO").length;
            const info = clientsInfo[c] || {};
            return (
              <div key={c} className="dk-client-card">
                <div className="dk-client-name">{c}</div>
                <div className="dk-client-meta">
                  {vids.length} vídeo{vids.length !== 1 ? "s" : ""} · {done} concluído{done !== 1 ? "s" : ""}
                </div>
                <div className="dk-client-contact-grid">
                  <input
                    placeholder="Empresa"
                    value={info.company || ""}
                    onChange={(e) => updateClientInfo(c, { company: e.target.value })}
                  />
                  <input
                    placeholder="Telefone"
                    value={info.phone || ""}
                    onChange={(e) => updateClientInfo(c, { phone: e.target.value })}
                  />
                  <input
                    placeholder="Instagram"
                    value={info.instagram || ""}
                    onChange={(e) => updateClientInfo(c, { instagram: e.target.value })}
                  />
                </div>
                {(info.contractedVideos ?? 0) > 0 && (
                  <div className="dk-package-bar">
                    Pacote: {info.usedVideos ?? 0} usados de {info.contractedVideos} · {Math.max((info.contractedVideos ?? 0) - (info.usedVideos ?? 0), 0)} restante(s)
                  </div>
                )}
                <div className="dk-client-videos">
                  {vids.map((v) => (
                    <button key={v.id} className="dk-client-video" onClick={() => setDetailId(v.id)}>
                      {v.title} <span className="dk-stagepill">{STAGES.find((s) => s.id === v.stage)?.label}</span>
                    </button>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {view === "financeiro" && role === "admin" && (
        <FinanceView
          clients={clients}
          videos={videos}
          clientsInfo={clientsInfo}
          onUpdateClient={updateClientInfo}
          onAddExpense={addExpense}
          onRemoveExpense={removeExpense}
        />
      )}

      {pinOpen && (
        <Modal onClose={() => setPinOpen(false)} title="Acesso admin">
          <div className="dk-form">
            <label>
              PIN
              <input
                type="password"
                autoFocus
                value={pinValue}
                onChange={(e) => {
                  setPinValue(e.target.value);
                  setPinError(false);
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    if (pinValue === ADMIN_PIN) {
                      setRole("admin");
                      setPinOpen(false);
                    } else {
                      setPinError(true);
                    }
                  }
                }}
                placeholder="Digite o PIN"
              />
            </label>
            {pinError && <span className="dk-pin-error">PIN incorreto.</span>}
            <div className="dk-form-actions">
              <button className="dk-btn ghost" onClick={() => setPinOpen(false)}>Cancelar</button>
              <button
                className="dk-btn primary"
                onClick={() => {
                  if (pinValue === ADMIN_PIN) {
                    setRole("admin");
                    setPinOpen(false);
                  } else {
                    setPinError(true);
                  }
                }}
              >
                Entrar
              </button>
            </div>
          </div>
        </Modal>
      )}

      {modalOpen && (
        <Modal onClose={() => setModalOpen(false)} title="Novo vídeo">
          <VideoForm
            form={form}
            setForm={setForm}
            onCancel={() => setModalOpen(false)}
            onSubmit={() => submitForm(false)}
            onSubmitAndAnother={() => submitForm(true)}
          />
        </Modal>
      )}

      {detailVideo && (
        <DetailDrawer
          video={detailVideo}
          onClose={() => setDetailId(null)}
          onStageChange={(s) => moveVideo(detailVideo.id, s)}
          onToggleChecklist={(k) => toggleChecklist(detailVideo.id, k)}
          onAddRevision={(text) => addRevision(detailVideo.id, text)}
          onUpdate={(patch) => updateVideo(detailVideo.id, patch)}
          onDelete={() => deleteVideo(detailVideo.id)}
        />
      )}
    </div>
  );
}

function StatChip({ label, value, onClick, active, tone }) {
  return (
    <button
      className={"dk-stat" + (active ? " active" : "") + (tone ? " tone-" + tone : "")}
      onClick={onClick}
    >
      <span className="dk-stat-value">{value}</span>
      <span className="dk-stat-label">{label}</span>
    </button>
  );
}

function VideoCard({ video, onDragStart, onOpen, onStageChange, onDragOverCard, onDropCard }) {
  const info = deadlineInfo(video);
  return (
    <div
      className={"dk-card level-" + info.level}
      draggable
      onDragStart={onDragStart}
      onDragOver={onDragOverCard}
      onDrop={onDropCard}
      onClick={onOpen}
    >
      <div className="dk-card-top">
        <span className="dk-card-client">{video.client}</span>
        {video.priority !== "Normal" && (
          <span className={"dk-prio prio-" + video.priority}>{video.priority}</span>
        )}
      </div>
      <div className="dk-card-title">{video.title}</div>
      <div className="dk-card-dates">
        Gravado: {fmtDateBR(video.shootDate)} · Entrega: {fmtDateBR(video.dueDate)}
      </div>
      <div className="dk-card-bottom">
        <span className={"dk-deadline tone-" + info.level}>
          {info.emoji} {info.label}
        </span>
        {video.editor && <span className="dk-editor">{video.editor}</span>}
      </div>
      <select
        className="dk-stage-select"
        value={video.stage}
        onClick={(e) => e.stopPropagation()}
        onChange={(e) => onStageChange(e.target.value)}
      >
        {STAGES.map((s) => (
          <option key={s.id} value={s.id}>
            {s.label}
          </option>
        ))}
      </select>
    </div>
  );
}

function TodaySection({ title, items, onOpen }) {
  return (
    <div className="dk-today-section">
      <div className="dk-today-title">
        {title} <span className="dk-today-count">{items.length}</span>
      </div>
      {items.length === 0 && <div className="dk-empty small">Nada aqui — ótimo sinal.</div>}
      <div className="dk-today-list">
        {items.map((v) => {
          const info = deadlineInfo(v);
          return (
            <button key={v.id} className="dk-today-item" onClick={() => onOpen(v.id)}>
              <span className="dk-card-client">{v.client}</span>
              <span className="dk-today-item-title">{v.title}</span>
              <span className={"dk-deadline tone-" + info.level}>{info.emoji} {info.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function Modal({ children, onClose, title }) {
  return (
    <div className="dk-modal-overlay" onClick={onClose}>
      <div className="dk-modal" onClick={(e) => e.stopPropagation()}>
        <div className="dk-modal-head">
          <span>{title}</span>
          <button className="dk-close" onClick={onClose}>✕</button>
        </div>
        <div className="dk-modal-body">{children}</div>
      </div>
    </div>
  );
}

function VideoForm({ form, setForm, onCancel, onSubmit, onSubmitAndAnother }) {
  const set = (k) => (e) =>
    setForm((f) => ({
      ...f,
      [k]: e.target.value,
      ...(k === "dueDate" ? { dueDateEdited: true } : {}),
    }));
  return (
    <div className="dk-form">
      <label>
        Cliente *
        <input value={form.client} onChange={set("client")} placeholder="Nome do cliente" />
      </label>
      <label>
        Nome do vídeo *
        <input value={form.title} onChange={set("title")} placeholder="Ex: Pré-lançamento" />
      </label>
      <div className="dk-form-row">
        <label>
          Data da gravação *
          <input type="date" value={form.shootDate} onChange={set("shootDate")} />
        </label>
        <label>
          Data de entrega (auto: +3 dias úteis)
          <input type="date" value={form.dueDate} onChange={set("dueDate")} />
        </label>
      </div>
      <div className="dk-form-row">
        <label>
          Editor/responsável
          <input value={form.editor} onChange={set("editor")} placeholder="Ex: Matheus" />
        </label>
        <label>
          Prioridade
          <select value={form.priority} onChange={set("priority")}>
            {PRIORITIES.map((p) => (
              <option key={p} value={p}>{p}</option>
            ))}
          </select>
        </label>
      </div>
      <div className="dk-form-row">
        <label>
          Formato
          <select value={form.format} onChange={set("format")}>
            {FORMATS.map((f) => (
              <option key={f} value={f}>{f}</option>
            ))}
          </select>
        </label>
        <label>
          Tipo de conteúdo
          <select value={form.type} onChange={set("type")}>
            {TYPES.map((t) => (
              <option key={t} value={t}>{t}</option>
            ))}
          </select>
        </label>
      </div>
      <label>
        Observações
        <textarea value={form.notes} onChange={set("notes")} rows={2} />
      </label>
      <div className="dk-form-row">
        <label>
          Link dos arquivos
          <input value={form.filesLink} onChange={set("filesLink")} placeholder="Drive, etc." />
        </label>
        <label>
          Link do roteiro/referência
          <input value={form.scriptLink} onChange={set("scriptLink")} />
        </label>
      </div>
      <div className="dk-form-actions">
        <button className="dk-btn ghost" onClick={onCancel}>Cancelar</button>
        <button className="dk-btn secondary" onClick={onSubmitAndAnother}>
          Salvar + adicionar outro desta gravação
        </button>
        <button className="dk-btn primary" onClick={onSubmit}>Salvar vídeo</button>
      </div>
    </div>
  );
}

function DetailDrawer({ video, onClose, onStageChange, onToggleChecklist, onAddRevision, onUpdate, onDelete }) {
  const [revisionText, setRevisionText] = useState("");
  const info = deadlineInfo(video);
  return (
    <div className="dk-drawer-overlay" onClick={onClose}>
      <div className="dk-drawer" onClick={(e) => e.stopPropagation()}>
        <div className="dk-drawer-head">
          <div>
            <div className="dk-card-client big">{video.client}</div>
            <div className="dk-drawer-title">{video.title}</div>
          </div>
          <button className="dk-close" onClick={onClose}>✕</button>
        </div>

        <div className="dk-drawer-section">
          <span className={"dk-deadline tone-" + info.level}>{info.emoji} {info.label}</span>
          <label className="dk-inline-label">
            Etapa
            <select value={video.stage} onChange={(e) => onStageChange(e.target.value)}>
              {STAGES.map((s) => (
                <option key={s.id} value={s.id}>{s.label}</option>
              ))}
            </select>
          </label>
        </div>

        <div className="dk-drawer-grid">
          <Field label="Gravado" value={fmtDateBR(video.shootDate)} />
          <Field label="Entrega" value={fmtDateBR(video.dueDate)} />
          <Field label="Editor" value={video.editor || "—"} />
          <Field label="Prioridade" value={video.priority} />
          <Field label="Formato" value={video.format} />
          <Field label="Tipo" value={video.type} />
        </div>

        {video.notes && (
          <div className="dk-drawer-section">
            <div className="dk-section-title">Observações</div>
            <div className="dk-notes">{video.notes}</div>
          </div>
        )}

        <div className="dk-drawer-section">
          <div className="dk-section-title">Links</div>
          <div className="dk-links">
            {video.filesLink && <a href={video.filesLink} target="_blank" rel="noreferrer">Arquivos</a>}
            {video.scriptLink && <a href={video.scriptLink} target="_blank" rel="noreferrer">Roteiro/referência</a>}
            {!video.filesLink && !video.scriptLink && <span className="dk-muted">Nenhum link cadastrado</span>}
          </div>
        </div>

        <div className="dk-drawer-section">
          <div className="dk-section-title">Checklist de finalização</div>
          <div className="dk-checklist">
            {CHECKLIST_DEFS.map(([key, label]) => (
              <label key={key} className="dk-check-item">
                <input
                  type="checkbox"
                  checked={!!video.checklist[key]}
                  onChange={() => onToggleChecklist(key)}
                />
                {label}
              </label>
            ))}
          </div>
        </div>

        {video.stage === "ALTERACAO" && (
          <div className="dk-drawer-section">
            <div className="dk-section-title">Registrar alteração</div>
            <textarea
              rows={2}
              placeholder="Ex: Trocar música e corrigir lettering aos 00:32."
              value={revisionText}
              onChange={(e) => setRevisionText(e.target.value)}
            />
            <button
              className="dk-btn secondary small"
              onClick={() => {
                if (revisionText.trim()) {
                  onAddRevision(revisionText.trim());
                  setRevisionText("");
                }
              }}
            >
              Adicionar alteração
            </button>
          </div>
        )}

        {video.revisions.length > 0 && (
          <div className="dk-drawer-section">
            <div className="dk-section-title">Alterações</div>
            {video.revisions.map((r) => (
              <div key={r.number} className="dk-revision">
                <strong>Alteração #{r.number}</strong>
                <span className="dk-muted"> · {r.requestedAt}</span>
                <div>{r.description}</div>
              </div>
            ))}
          </div>
        )}

        <div className="dk-drawer-section">
          <div className="dk-section-title">Histórico</div>
          <div className="dk-history">
            {video.history.map((h, i) => (
              <div key={i} className="dk-history-item">
                <span className="dk-history-dot" />
                <span className="dk-history-at">{h.at}</span>
                <span>{h.text}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="dk-drawer-section">
          <button className="dk-btn ghost danger" onClick={onDelete}>Excluir vídeo</button>
        </div>
      </div>
    </div>
  );
}

function FinanceView({ clients, videos, clientsInfo, onUpdateClient, onAddExpense, onRemoveExpense }) {
  const [expDesc, setExpDesc] = useState("");
  const [expValue, setExpValue] = useState("");
  const expenses = clientsInfo.__expenses || [];

  const receita = clients.reduce((sum, c) => sum + (Number((clientsInfo[c] || {}).packagePrice) || 0), 0);
  const despesas = expenses.reduce((sum, e) => sum + (Number(e.value) || 0), 0);
  const resultado = receita - despesas;
  const fmt = (n) => n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

  return (
    <div className="dk-finance">
      <div className="dk-finance-summary">
        <div className="dk-fin-card">
          <span className="dk-fin-label">Receita mensal (planos ativos)</span>
          <span className="dk-fin-value good">{fmt(receita)}</span>
        </div>
        <div className="dk-fin-card">
          <span className="dk-fin-label">Despesas do mês</span>
          <span className="dk-fin-value bad">{fmt(despesas)}</span>
        </div>
        <div className="dk-fin-card">
          <span className="dk-fin-label">Resultado</span>
          <span className={"dk-fin-value " + (resultado >= 0 ? "good" : "bad")}>{fmt(resultado)}</span>
        </div>
      </div>

      <div className="dk-section-title" style={{ marginTop: 18 }}>Planos e contratos por cliente</div>
      <div className="dk-fin-table">
        <div className="dk-fin-row dk-fin-head">
          <span>Cliente</span>
          <span>Plano</span>
          <span>Valor mensal</span>
          <span>Vídeos contratados</span>
          <span>Usados</span>
        </div>
        {clients.length === 0 && <div className="dk-empty">Nenhum cliente cadastrado ainda.</div>}
        {clients.map((c) => {
          const info = clientsInfo[c] || {};
          return (
            <div className="dk-fin-row" key={c}>
              <span className="dk-fin-client">{c}</span>
              <input
                value={info.packageName || ""}
                placeholder="Ex: Profissional"
                onChange={(e) => onUpdateClient(c, { packageName: e.target.value })}
              />
              <input
                type="number"
                value={info.packagePrice || ""}
                placeholder="R$"
                onChange={(e) => onUpdateClient(c, { packagePrice: e.target.value })}
              />
              <input
                type="number"
                value={info.contractedVideos || ""}
                placeholder="0"
                onChange={(e) => onUpdateClient(c, { contractedVideos: e.target.value })}
              />
              <input
                type="number"
                value={info.usedVideos || ""}
                placeholder="0"
                onChange={(e) => onUpdateClient(c, { usedVideos: e.target.value })}
              />
            </div>
          );
        })}
      </div>

      <div className="dk-section-title" style={{ marginTop: 18 }}>Despesas</div>
      <div className="dk-expense-add">
        <input placeholder="Descrição" value={expDesc} onChange={(e) => setExpDesc(e.target.value)} />
        <input
          type="number"
          placeholder="Valor"
          value={expValue}
          onChange={(e) => setExpValue(e.target.value)}
        />
        <button
          className="dk-btn secondary small"
          onClick={() => {
            if (expDesc.trim() && expValue) {
              onAddExpense(expDesc.trim(), expValue);
              setExpDesc("");
              setExpValue("");
            }
          }}
        >
          Adicionar
        </button>
      </div>
      <div className="dk-expense-list">
        {expenses.length === 0 && <div className="dk-empty small">Nenhuma despesa lançada.</div>}
        {expenses.map((e) => (
          <div key={e.id} className="dk-expense-item">
            <span>{e.desc}</span>
            <span>{fmt(Number(e.value) || 0)}</span>
            <button className="dk-close" onClick={() => onRemoveExpense(e.id)}>✕</button>
          </div>
        ))}
      </div>
    </div>
  );
}

function Field({ label, value }) {
  return (
    <div className="dk-field">
      <span className="dk-field-label">{label}</span>
      <span className="dk-field-value">{value}</span>
    </div>
  );
}

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=Montserrat:wght@400;500;600;700;800&display=swap');

.dk-root {
  --bg: #0d1e11;
  --bg-panel: #142c1a;
  --bg-card: #17331e;
  --border: #2a4a32;
  --gold: #c6a352;
  --gold-soft: #e4c878;
  --text: #f3f1ea;
  --text-dim: #a8bdae;
  --red: #e2554a;
  --orange: #e2924a;
  --yellow: #d8c24a;
  --green: #6fae7c;
  --radius: 10px;
  font-family: 'Montserrat', sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  padding: 18px 22px 40px;
  box-sizing: border-box;
}
.dk-root * { box-sizing: border-box; }

.dk-header {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.dk-brand { display: flex; align-items: center; gap: 10px; }
.dk-logo { height: 46px; width: auto; object-fit: contain; border-radius: 6px; }
.dk-brand-text { display: flex; flex-direction: column; line-height: 1.1; }
.dk-brand-title { font-family: 'Playfair Display', serif; font-size: 22px; letter-spacing: 2px; color: var(--text); }
.dk-brand-sub { font-size: 9px; letter-spacing: 1.6px; color: var(--gold); font-weight: 600; }

.dk-nav { display: flex; gap: 6px; margin-left: 12px; }
.dk-nav-btn {
  background: transparent; border: 1px solid var(--border); color: var(--text-dim);
  padding: 7px 14px; border-radius: 999px; font-size: 12.5px; font-weight: 600;
  cursor: pointer; transition: all .15s;
}
.dk-nav-btn:hover { color: var(--text); border-color: var(--gold); }
.dk-nav-btn.active { background: var(--gold); color: #16240f; border-color: var(--gold); }

.dk-new-btn {
  margin-left: auto; background: linear-gradient(135deg, var(--gold-soft), var(--gold));
  color: #16240f; border: none; padding: 10px 18px; border-radius: 8px;
  font-weight: 700; font-size: 13px; cursor: pointer; letter-spacing: .3px;
  box-shadow: 0 4px 14px rgba(198,163,82,.25);
}
.dk-new-btn:hover { filter: brightness(1.06); }

.dk-stats { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; align-items: center; }
.dk-stat {
  background: var(--bg-panel); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 8px 14px; display: flex; flex-direction: column; align-items: flex-start;
  cursor: pointer; min-width: 108px; transition: border-color .15s;
}
.dk-stat:hover { border-color: var(--gold); }
.dk-stat.active { border-color: var(--gold); background: #1c3a23; }
.dk-stat-value { font-size: 20px; font-weight: 800; color: var(--text); }
.dk-stat-label { font-size: 10.5px; color: var(--text-dim); letter-spacing: .3px; }
.dk-stat.tone-late .dk-stat-value { color: var(--red); }
.dk-stat.tone-done .dk-stat-value { color: var(--green); }
.dk-savebadge { font-size: 10.5px; color: var(--text-dim); margin-left: auto; }
.dk-savebadge.error { color: var(--red); }

.dk-filters { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; align-items: center; }
.dk-quick { display: flex; gap: 6px; flex-wrap: wrap; }
.dk-chip {
  background: transparent; border: 1px solid var(--border); color: var(--text-dim);
  padding: 6px 12px; border-radius: 999px; font-size: 12px; cursor: pointer; font-weight: 500;
}
.dk-chip.active { background: var(--bg-card); color: var(--gold-soft); border-color: var(--gold); }
.dk-filters select {
  background: var(--bg-panel); color: var(--text); border: 1px solid var(--border);
  border-radius: 8px; padding: 6px 10px; font-size: 12px; font-family: inherit;
}
.dk-search {
  background: var(--bg-panel); color: var(--text); border: 1px solid var(--border);
  border-radius: 8px; padding: 7px 12px; font-size: 12.5px; min-width: 200px; font-family: inherit;
}

.dk-board { display: flex; gap: 12px; overflow-x: auto; padding-bottom: 14px; }
.dk-column {
  background: var(--bg-panel); border: 1px solid var(--border); border-radius: 12px;
  min-width: 250px; max-width: 270px; flex: 1 0 250px; padding: 10px; display: flex; flex-direction: column;
  max-height: calc(100vh - 220px);
}
.dk-col-head { display: flex; justify-content: space-between; align-items: baseline; }
.dk-col-title { font-weight: 700; font-size: 13px; letter-spacing: .3px; }
.dk-col-count { font-size: 11px; color: var(--text-dim); background: var(--bg-card); padding: 1px 7px; border-radius: 999px; }
.dk-col-hint { font-size: 10px; color: var(--text-dim); margin-bottom: 8px; }
.dk-col-body { display: flex; flex-direction: column; gap: 8px; overflow-y: auto; padding-right: 2px; }

.dk-card {
  background: var(--bg-card); border: 1px solid var(--border); border-left: 3px solid var(--border);
  border-radius: 8px; padding: 10px 11px; cursor: grab; transition: transform .1s, border-color .15s;
}
.dk-card:hover { border-color: var(--gold); transform: translateY(-1px); }
.dk-card.level-late { border-left-color: var(--red); }
.dk-card.level-today { border-left-color: var(--red); }
.dk-card.level-tomorrow { border-left-color: var(--orange); }
.dk-card.level-soon { border-left-color: var(--yellow); }
.dk-card.level-ok { border-left-color: var(--green); }
.dk-card-top { display: flex; justify-content: space-between; align-items: center; }
.dk-card-client { font-weight: 800; font-size: 13.5px; color: var(--gold-soft); }
.dk-card-client.big { font-size: 18px; }
.dk-prio { font-size: 9.5px; font-weight: 700; padding: 2px 7px; border-radius: 999px; letter-spacing: .3px; }
.prio-Alta { background: #4a3212; color: var(--orange); }
.prio-Urgente { background: #4a1f1c; color: var(--red); }
.dk-card-title { font-size: 12.5px; margin: 3px 0 6px; color: var(--text); }
.dk-card-dates { font-size: 10.5px; color: var(--text-dim); margin-bottom: 6px; }
.dk-card-bottom { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }
.dk-deadline { font-size: 10.5px; font-weight: 700; }
.dk-deadline.tone-late, .dk-deadline.tone-today { color: var(--red); }
.dk-deadline.tone-tomorrow { color: var(--orange); }
.dk-deadline.tone-soon { color: var(--yellow); }
.dk-deadline.tone-ok { color: var(--green); }
.dk-deadline.tone-done { color: var(--green); }
.dk-editor { font-size: 10px; color: var(--text-dim); background: var(--bg-panel); padding: 2px 8px; border-radius: 999px; }
.dk-stage-select {
  width: 100%; background: var(--bg-panel); color: var(--text-dim); border: 1px solid var(--border);
  border-radius: 6px; font-size: 10.5px; padding: 4px 6px; font-family: inherit;
}
.dk-empty { color: var(--text-dim); font-size: 11.5px; text-align: center; padding: 14px 0; }
.dk-empty.small { padding: 6px 0; }

.dk-today { display: flex; flex-direction: column; gap: 18px; max-width: 720px; }
.dk-today-title { font-weight: 700; font-size: 14px; display: flex; align-items: center; gap: 8px; }
.dk-today-count { font-size: 11px; color: var(--text-dim); }
.dk-today-list { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }
.dk-today-item {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  background: var(--bg-panel); border: 1px solid var(--border); border-radius: 8px;
  padding: 8px 12px; cursor: pointer; text-align: left; font-family: inherit; color: var(--text);
}
.dk-today-item-title { flex: 1; font-size: 12px; color: var(--text-dim); }

.dk-clients { display: flex; flex-direction: column; gap: 12px; max-width: 760px; }
.dk-client-card { background: var(--bg-panel); border: 1px solid var(--border); border-radius: 10px; padding: 14px; }
.dk-client-name { font-family: 'Playfair Display', serif; font-size: 17px; color: var(--gold-soft); }
.dk-client-meta { font-size: 11px; color: var(--text-dim); margin: 3px 0 8px; }
.dk-client-videos { display: flex; flex-direction: column; gap: 5px; }
.dk-client-video {
  background: transparent; border: none; color: var(--text); text-align: left; font-size: 12px;
  padding: 5px 0; cursor: pointer; font-family: inherit; display: flex; gap: 8px; align-items: center;
}
.dk-stagepill { font-size: 9.5px; color: var(--text-dim); background: var(--bg-card); padding: 1px 7px; border-radius: 999px; }

.dk-modal-overlay, .dk-drawer-overlay {
  position: fixed; inset: 0; background: rgba(6,14,8,.65); display: flex; z-index: 50;
  align-items: center; justify-content: center;
}
.dk-drawer-overlay { justify-content: flex-end; }
.dk-modal {
  background: var(--bg-panel); border: 1px solid var(--border); border-radius: 14px;
  width: 560px; max-width: 92vw; max-height: 88vh; overflow-y: auto;
}
.dk-drawer {
  background: var(--bg-panel); border-left: 1px solid var(--border); width: 420px; max-width: 92vw;
  height: 100%; overflow-y: auto; padding: 20px;
}
.dk-modal-head, .dk-drawer-head {
  display: flex; justify-content: space-between; align-items: flex-start; padding: 16px 18px;
  border-bottom: 1px solid var(--border); font-weight: 700;
}
.dk-drawer-head { padding: 0 0 14px; }
.dk-drawer-title { font-size: 13.5px; color: var(--text-dim); margin-top: 2px; }
.dk-close { background: transparent; border: none; color: var(--text-dim); font-size: 15px; cursor: pointer; }
.dk-modal-body { padding: 16px 18px; }

.dk-form { display: flex; flex-direction: column; gap: 12px; }
.dk-form label { display: flex; flex-direction: column; gap: 4px; font-size: 11.5px; color: var(--text-dim); flex: 1; }
.dk-form-row { display: flex; gap: 12px; }
.dk-form input, .dk-form select, .dk-form textarea {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: 7px;
  padding: 8px 10px; color: var(--text); font-size: 12.5px; font-family: inherit;
}
.dk-form-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 6px; flex-wrap: wrap; }

.dk-btn { border: none; border-radius: 7px; padding: 8px 14px; font-size: 12px; font-weight: 700; cursor: pointer; font-family: inherit; }
.dk-btn.primary { background: linear-gradient(135deg, var(--gold-soft), var(--gold)); color: #16240f; }
.dk-btn.secondary { background: var(--bg-card); color: var(--gold-soft); border: 1px solid var(--gold); }
.dk-btn.ghost { background: transparent; color: var(--text-dim); border: 1px solid var(--border); }
.dk-btn.danger { color: var(--red); border-color: var(--red); }
.dk-btn.small { padding: 6px 10px; font-size: 11px; margin-top: 6px; }

.dk-drawer-section { margin-bottom: 16px; }
.dk-drawer-section:has(.dk-inline-label) { display: flex; justify-content: space-between; align-items: center; }
.dk-inline-label { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--text-dim); }
.dk-inline-label select { background: var(--bg-card); color: var(--text); border: 1px solid var(--border); border-radius: 6px; padding: 4px 8px; font-family: inherit; }
.dk-drawer-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 16px; }
.dk-field { display: flex; flex-direction: column; gap: 2px; }
.dk-field-label { font-size: 10px; color: var(--text-dim); text-transform: uppercase; letter-spacing: .4px; }
.dk-field-value { font-size: 12.5px; }
.dk-section-title { font-size: 11px; color: var(--gold-soft); font-weight: 700; text-transform: uppercase; letter-spacing: .5px; margin-bottom: 6px; }
.dk-notes { font-size: 12.5px; color: var(--text-dim); background: var(--bg-card); padding: 8px 10px; border-radius: 7px; }
.dk-links { display: flex; gap: 12px; }
.dk-links a { color: var(--gold-soft); font-size: 12px; }
.dk-muted { color: var(--text-dim); font-size: 12px; }
.dk-checklist { display: flex; flex-direction: column; gap: 6px; }
.dk-check-item { display: flex; align-items: center; gap: 8px; font-size: 12.5px; }
.dk-revision { background: var(--bg-card); padding: 8px 10px; border-radius: 7px; font-size: 12px; margin-bottom: 6px; }
.dk-drawer textarea { width: 100%; background: var(--bg-card); border: 1px solid var(--border); border-radius: 7px; color: var(--text); padding: 8px; font-family: inherit; font-size: 12px; margin-bottom: 6px; }
.dk-history { display: flex; flex-direction: column; gap: 8px; }
.dk-history-item { display: flex; align-items: baseline; gap: 8px; font-size: 12px; color: var(--text-dim); }
.dk-history-dot { width: 5px; height: 5px; border-radius: 999px; background: var(--gold); flex-shrink: 0; }
.dk-history-at { color: var(--gold-soft); font-size: 10.5px; min-width: 78px; }

@media (max-width: 720px) {
  .dk-header { gap: 10px; }
  .dk-nav { margin-left: 0; }
  .dk-new-btn { margin-left: 0; order: 3; width: 100%; }
  .dk-board { flex-wrap: nowrap; }
}
`;
